<?php
declare(strict_types=1);
define('BASE_PATH',dirname(__DIR__));require BASE_PATH.'/app/Support/helpers.php';spl_autoload_register(static function(string $class):void{$prefix='App\\';if(str_starts_with($class,$prefix))require BASE_PATH.'/app/'.str_replace('\\','/',substr($class,strlen($prefix))).'.php';});
use App\Import\CourseImportService;
$config=require BASE_PATH.'/config/database.php';$testDb='gbu_cse_curriculum_'.bin2hex(random_bytes(4));$server=new PDO("mysql:host={$config['host']};port={$config['port']};charset=utf8mb4",$config['username'],$config['password'],[PDO::ATTR_ERRMODE=>PDO::ERRMODE_EXCEPTION,PDO::ATTR_EMULATE_PREPARES=>true]);
try{$schema=str_replace('gbu_exam_operations',$testDb,file_get_contents(BASE_PATH.'/database/schema.sql'));$server->exec($schema);$seed=str_replace('gbu_exam_operations',$testDb,file_get_contents(BASE_PATH.'/database/seed.sql'));$server->exec($seed);$pdo=new PDO("mysql:host={$config['host']};port={$config['port']};dbname={$testDb};charset=utf8mb4",$config['username'],$config['password'],[PDO::ATTR_ERRMODE=>PDO::ERRMODE_EXCEPTION,PDO::ATTR_DEFAULT_FETCH_MODE=>PDO::FETCH_ASSOC]);$pdo->exec("INSERT INTO users(role_id,username,password_hash,name,status) SELECT id,'dataset_test','test','Dataset Test','active' FROM roles WHERE code='admin'");$user=(int)$pdo->lastInsertId();$service=new CourseImportService($pdo);$batch=$service->stage(BASE_PATH.'/storage/demo-data/btech_cse_2022_23_curriculum_upload.csv','btech_cse_2022_23_curriculum_upload.csv',$user);$summary=$pdo->query("SELECT total_rows,valid_rows,invalid_rows FROM import_batches WHERE id={$batch}")->fetch();assert((int)$summary['total_rows']===94&&(int)$summary['valid_rows']===94&&(int)$summary['invalid_rows']===0);$pdo->beginTransaction();$count=$service->commit($batch,$user);$pdo->commit();assert($count===94);assert((int)$pdo->query("SELECT COUNT(*) FROM programme_courses pc JOIN programmes p ON p.id=pc.programme_id WHERE p.code='UCS'")->fetchColumn()===94);echo "B.Tech CSE curriculum dataset: PASS (94/94 valid and committed)\n";}finally{$server->exec("DROP DATABASE IF EXISTS `{$testDb}`");}
